CREATE TABLE IF NOT EXISTS public.ripple_fieldroutes_assignments (location_id text NOT NULL, fieldroutes_appointment_id text NOT NULL, assigned_technicians jsonb NOT NULL DEFAULT '[]'::jsonb, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (location_id, fieldroutes_appointment_id)); ALTER TABLE public.ripple_fieldroutes_assignments ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.ripple_fieldroutes_assignments FROM PUBLIC,anon,authenticated; GRANT SELECT,INSERT,UPDATE ON public.ripple_fieldroutes_assignments TO service_role; CREATE OR REPLACE FUNCTION public.ripple_link_fieldroutes_job(p_location_id text,p_ghl_job_id text,p_fieldroutes_appointment_id text) RETURNS integer LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE n integer; BEGIN IF current_user <> 'service_role' THEN RAISE EXCEPTION 'service_role required'; END IF; IF nullif(p_location_id,'') IS NULL OR nullif(p_ghl_job_id,'') IS NULL OR nullif(p_fieldroutes_appointment_id,'') IS NULL THEN RETURN 0; END IF; UPDATE public.jobs j SET fieldroutes_appointment_id=p_fieldroutes_appointment_id,assigned_technicians=CASE WHEN a.location_id IS NOT NULL AND jsonb_array_length(a.assigned_technicians)>0 THEN a.assigned_technicians ELSE j.assigned_technicians END,technician_source=CASE WHEN a.location_id IS NOT NULL AND jsonb_array_length(a.assigned_technicians)>0 THEN 'fieldroutes' ELSE j.technician_source END FROM (SELECT p_location_id AS location_id,p_fieldroutes_appointment_id AS fieldroutes_appointment_id) x LEFT JOIN public.ripple_fieldroutes_assignments a ON a.location_id=x.location_id AND a.fieldroutes_appointment_id=x.fieldroutes_appointment_id WHERE j.location_id=p_location_id AND j.ghl_job_id=p_ghl_job_id; GET DIAGNOSTICS n = ROW_COUNT; RETURN n; END $$; REVOKE ALL ON FUNCTION public.ripple_link_fieldroutes_job(text,text,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.ripple_link_fieldroutes_job(text,text,text) TO service_role; CREATE OR REPLACE FUNCTION public.ripple_store_fr_technicians(p_office_id text,p_appointment_id text,p_technicians jsonb) RETURNS integer LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE loc text; n integer; BEGIN IF current_user <> 'service_role' THEN RAISE EXCEPTION 'service_role required'; END IF; IF nullif(p_office_id,'') IS NULL OR nullif(p_appointment_id,'') IS NULL OR jsonb_typeof(p_technicians) IS DISTINCT FROM 'array' OR jsonb_array_length(p_technicians)=0 THEN RETURN 0; END IF; SELECT location_id INTO loc FROM public.config WHERE fieldroutes_office_id::text=p_office_id LIMIT 1; IF loc IS NULL THEN RETURN 0; END IF; INSERT INTO public.ripple_fieldroutes_assignments(location_id,fieldroutes_appointment_id,assigned_technicians,updated_at) VALUES(loc,p_appointment_id,p_technicians,now()) ON CONFLICT(location_id,fieldroutes_appointment_id) DO UPDATE SET assigned_technicians=excluded.assigned_technicians,updated_at=now(); UPDATE public.jobs SET assigned_technicians=p_technicians, technician_source='fieldroutes' WHERE location_id=loc AND fieldroutes_appointment_id=p_appointment_id; GET DIAGNOSTICS n=ROW_COUNT; RETURN n; END $$; REVOKE ALL ON FUNCTION public.ripple_store_fr_technicians(text,text,jsonb) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.ripple_store_fr_technicians(text,text,jsonb) TO service_role;